class Solution {
  public int[] maxTargetNodes(int[][] edges1, int[][] edges2, int k) {
    int[] within1 = countWithin(edges1, k);
    int best2 = 0;
    if (k > 0) {
      for (int c : countWithin(edges2, k - 1)) best2 = Math.max(best2, c);
    }
    int[] ans = new int[within1.length];
    for (int i = 0; i < ans.length; i++) ans[i] = within1[i] + best2;
    return ans;
  }

  // for every node of the tree: how many nodes lie within `limit` edges
  private int[] countWithin(int[][] edges, int limit) {
    int n = edges.length + 1;
    int[] head = new int[n], nxt = new int[2 * edges.length], to = new int[2 * edges.length];
    Arrays.fill(head, -1);
    int e = 0;
    for (int[] ed : edges) {
      to[e] = ed[1];
      nxt[e] = head[ed[0]];
      head[ed[0]] = e++;
      to[e] = ed[0];
      nxt[e] = head[ed[1]];
      head[ed[1]] = e++;
    }
    int[] counts = new int[n], queue = new int[n], dist = new int[n], parent = new int[n];
    for (int s = 0; s < n; s++) {
      int qh = 0, qt = 0, total = 0;
      queue[qt++] = s;
      dist[s] = 0;
      parent[s] = -1;
      // BFS limited to `limit` levels; a tree has no cycles, so remembering the parent is enough
      while (qh < qt) {
        int u = queue[qh++];
        total++;
        if (dist[u] == limit) continue;
        for (int ei = head[u]; ei != -1; ei = nxt[ei]) {
          int v = to[ei];
          if (v == parent[u]) continue;
          parent[v] = u;
          dist[v] = dist[u] + 1;
          queue[qt++] = v;
        }
      }
      counts[s] = total;
    }
    return counts;
  }
}
